+/* 결과 근처에서 여는 보기(자세히 보기·손실이 커진 때 보기)가 함께 쓰는 모양이다. */
+
+.panel {
+  display: flex;
+  flex-direction: column;
+  gap: 22px;
+  min-width: 0;
+  padding: 22px 24px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 14px;
+  background: var(--thorp-surface);
+}
+
+.panelHeader {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 8px 16px;
+}
+
+.panelTitle {
+  margin: 0;
+  font-size: 1.2rem;
+  letter-spacing: -0.02em;
+}
+
+.panelTitle:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset);
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
+  gap: 18px 24px;
+}
+
+.item {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  min-width: 0;
+}
+
+.itemTitle {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.85rem;
+  font-weight: 600;
+}
+
+.subTitle {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.8rem;
+  font-weight: 600;
+}
+
+.value {
+  margin: 0;
+  font-family: var(--thorp-font-mono);
+  font-size: 1.05rem;
+  font-variant-numeric: tabular-nums;
+  overflow-wrap: anywhere;
+}
+
+.copy {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.84rem;
+  line-height: 1.7;
+  overflow-wrap: anywhere;
+}
+
+.muted {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: 0.78rem;
+  line-height: 1.6;
+}
+
+/* 계산이 제한되었거나 아직 제공되지 않는 항목. 값 자리에 0을 두지 않고 이 표시만 둔다(FR-009). */
+.limited {
+  margin: 0;
+  padding-left: 10px;
+  border-left: 2px solid var(--thorp-warning);
