+
+.table caption {
+  padding-bottom: 6px;
+  color: var(--thorp-muted);
+  font-size: 0.76rem;
+  text-align: left;
+}
+
+.table th,
+.table td {
+  padding: 6px 10px;
+  border-bottom: 1px solid var(--thorp-line);
+  text-align: left;
+  white-space: nowrap;
+}
+
+.table th {
+  color: var(--thorp-copy);
+  font-weight: 600;
+}
+
+/* 열 때 받는 자원 한 자리. 다시 받을 때 초점을 받아 두는 자리라 테두리를 그리지 않는다. */
