+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  min-width: 0;
+}
+
+.area:focus {
+  outline: none;
+}
+
+.row {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 8px 12px;
+}
+
+.form {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: flex-end;
+  gap: 10px 14px;
+}
+
+.field {
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+}
+
+.field input,
+.field select {
+  min-height: 32px;
+  padding: 4px 8px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 8px;
+  background: var(--thorp-surface-raised);
+  color: var(--thorp-foreground);
+  font: inherit;
+  font-size: 0.84rem;
+}
+
+.field input:focus-visible,
+.field select:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset);
+}
+
+.alert {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.84rem;
+  line-height: 1.6;
+}
+
+/* 001 대표 상품 정보 패널(`InstrumentProfilePanel`)은 모양을 쓰는 쪽이 정한다. 섹터 선택 화면의 규칙을 줄여 옮긴다. */
+.profile [data-slot='profile-panel'] {
+  padding: 10px 0 2px;
+}
+
+.profile [data-slot='profile-loading'],
+.profile [data-slot='composition-caveat'],
+.profile [data-slot='profile-methodology'],
+.profile [data-slot='profile-survivorship'],
+.profile [data-slot='profile-sample'] {
+  margin: 0 0 8px;
+  color: var(--thorp-copy);
+  font-size: 0.8rem;
+  line-height: 1.7;
+}
+
+.profile [data-slot='composition-caveat'] {
+  padding-left: 10px;
+  border-left: 2px solid var(--thorp-warning);
+}
+
+.profile [data-slot='composition-bar'] {
+  display: flex;
+  width: 100%;
+  height: 10px;
+  margin: 10px 0;
+  overflow: hidden;
+  border-radius: 3px;
+  background: var(--thorp-surface-muted);
+}
+
+.profile [data-slot='composition-segment'] {
+  flex: none;
+  border-right: 1px solid var(--thorp-surface);
+  background: var(--thorp-accent);
+}
+
+.profile [data-slot='composition-segment'][data-rest='true'] {
+  background: var(--thorp-line-strong);
+}
+
+.profile [data-slot='holdings'] {
+  display: grid;
+  gap: 2px;
+  margin: 0 0 10px;
+  padding: 0;
+  list-style: none;
+}
+
+.profile [data-slot='holding'] {
+  display: flex;
+  justify-content: space-between;
+  gap: 8px;
+  font-size: 0.82rem;
+  font-variant-numeric: tabular-nums;
+}
+
+.profile [data-slot='profile-facts'] {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 24px;
+  margin: 0 0 10px;
+}
+
+.profile [data-slot='profile-facts'] dt {
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+}
+
+.profile [data-slot='profile-facts'] dd {
+  margin: 2px 0 0;
+  font-size: 0.84rem;
+}
+
+.profile [data-slot='profile-source'] {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+}
+
+.profileList {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+@media (max-width: 600px) {
+  .panel {
+    padding: 18px 16px;
+  }
+}

